-        var channel = aRequest.QueryInterface(Ci.nsIChannel);
-        dump("***** onSecurityChange request: " + channel.URI.spec + "\n");
-      } catch (e) {}
-    }
-  },
-
-  onContentBlockingEvent() {},
-
